#!/usr/bin/env python3

"""Fully generated by Claude Opus 5.5"""

r"""
chatnetwork.py - build an interactive network page of who talks to whom in the
Utonish live chats, from the UtonishLogger pytchat exports.

    data/chat/<video id>/<YYYY-MM-DD>.jsonl

Three kinds of connection are measured between two accounts:

  mention       A writes B's name (@handle, or a recognisable part of it such as
                "Napri" for @Naprisback) while B was active in the last 15 minutes
  conversation  A writes a chat message (not just a vote) shortly after B wrote one
                (default: within 90 s) - people taking turns in the chat
  together      both were voting in the same 5-minute slots (co-presence), shown as
                the share of the smaller account's active time they overlap

Profile pictures are taken from data/profile_pictures/<channel id>/<image id>.png
(the picture each account used in its latest message in the selected period) and
embedded in the page, shrunk to 96 px if Pillow is installed (pip install pillow).

Usage
    python chatnetwork.py data                                  # everything -> chat_network.html
    python chatnetwork.py data --stream ICV --from 2026-10-01 --to 2026-10-31 -o october_icv.html
    python chatnetwork.py data --stream CVC2 --min-messages 200 --no-together

--stream takes ICV, CV, CVC, CVC2 or a video id (ids starting with "-" need the =
form: --stream=-fesy2kdDxo). --from/--to take YYYY-MM-DD or "YYYY-MM-DD HH:MM" in
this computer's time zone (the logger names its files in it).

Requires Python 3.9+ and numpy. The page is a single self-contained HTML file
(no internet needed); open it in any browser.
"""
from __future__ import annotations

import argparse
import base64
